SINA_SMART["parasito-amoebiasis"] = {"lecture":"parasito-amoebiasis","title":"Amoebiasis","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"parasito-amoebiasis:e0","text":"Only Entamoeba histolytica is pathogenic among the 9 human gut amoebae.","topic":"The big picture","sec":0,"importance":"core","highYield":"historically-high-yield"},{"id":"parasito-amoebiasis:e1","text":"90% asymptomatic, 10% disease; 3rd parasitic cause of death.","topic":"The big picture","sec":0,"importance":"core","highYield":"untested"},{"id":"parasito-amoebiasis:e2","text":"Histolytica form: 20-40 µm, haematophagous, invasive.","topic":"The parasite","sec":1,"importance":"core","highYield":"untested"},{"id":"parasito-amoebiasis:e3","text":"Minuta: commensal; cyst (4 nuclei): infective, chlorine-resistant.","topic":"The parasite","sec":1,"importance":"core","highYield":"historically-high-yield"},{"id":"parasito-amoebiasis:e4","text":"Faecal-oral (water, raw vegetables, hands) and oral-anal sex.","topic":"Epidemiology and cycle","sec":2,"importance":"core","highYield":"untested"},{"id":"parasito-amoebiasis:e5","text":"Short direct (monoxenous) cycle.","topic":"Epidemiology and cycle","sec":2,"importance":"core","highYield":"untested"},{"id":"parasito-amoebiasis:e6","text":"Dysentery: mucus + blood without faeces, épreintes, tenesmus.","topic":"Clinical forms","sec":3,"importance":"core","highYield":"untested"},{"id":"parasito-amoebiasis:e7","text":"Liver abscess within 5 months in 95%: Fontan triad, anchovy-sauce pus.","topic":"Clinical forms","sec":3,"importance":"core","highYield":"historically-high-yield"},{"id":"parasito-amoebiasis:e10","text":"Aspirate or drain large abscesses.","topic":"Diagnosis, treatment and prevention","sec":4,"importance":"core","highYield":"untested"},{"id":"parasito-amoebiasis:e8","text":"Intestinal: 3 stool exams; visceral: ELISA serology.","topic":"Diagnosis, treatment and prevention","sec":4,"importance":"core","highYield":"untested"},{"id":"parasito-amoebiasis:e9","text":"Tissue amoebicide (metronidazole) then contact amoebicide (paromomycin).","topic":"Diagnosis, treatment and prevention","sec":4,"importance":"core","highYield":"untested"}],"vmap":{},"mlevel":{"69lt7":"a","18uoxao":"a","ya3bea":"a","9k1guk":"a","13ptuh8":"a","tl7lz":"a","oq8du8":"a","me5lwn":"a","d6bx8a":"a","csxcfp":"a","1mclq59":"a","1wjok4n":"a","odzhu5":"a","16qfuj9":"a","1vnpe5i":"a"},"mapCounts":{"verified":0,"auto":15,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"parasito-amoebiasis:e0":{"s":0,"u":["Only Entamoeba histolytica is pathogenic among the 9 human gut amoebae.","Of the 9 amoebae living in the human gut, only E. histolytica is pathogenic ; E. dispar and E. moshkovskii look identical but are harmless, as are E. coli , E. hartmanni , Endolimax nana and others.","Amoebiasis is carriage of Entamoeba histolytica , with or without symptoms."],"dp":[]},"parasito-amoebiasis:e1":{"s":0,"u":["90% asymptomatic, 10% disease; 3rd parasitic cause of death.","It is strictly human (caecum and sigmoid-rectum), worldwide, linked to the faecal hazard , commoner in hot, humid, poorly sanitised regions, and the 3rd parasitic cause of death .","90% of infections are asymptomatic (amoebiasis-infection); 10% are symptomatic (amoebiasis-disease): intestinal (colon) and extra-intestinal (mainly liver , then lung)."],"dp":[]},"parasito-amoebiasis:e2":{"s":1,"u":["Histolytica form: 20-40 µm, haematophagous, invasive.","Histolytica trophozoite : 20-40 µm, fast unidirectional pseudopods, nucleus with central karyosome and fine peripheral chromatin, ingests red cells (haematophagous) : the invasive, pathogenic form causing necrosis."],"dp":[]},"parasito-amoebiasis:e3":{"s":1,"u":["Minuta: commensal; cyst (4 nuclei): infective, chlorine-resistant.","Cyst : spherical 10-15 µm, 1 to 4 nuclei when mature, chromatoid bodies; the infective, resistant form : resists chlorine , killed by freezing (-5 °C) and above 40 °C.","Minuta : 10-15 µm, non-haematophagous commensal of the colonic lumen in healthy carriers."],"dp":[]},"parasito-amoebiasis:e4":{"s":2,"u":["Faecal-oral (water, raw vegetables, hands) and oral-anal sex.","Faecal-oral : contaminated water, raw vegetables fertilised with human waste or sewage, dirty hands (cysts under nails); also oral-anal sexual contact ."],"dp":[]},"parasito-amoebiasis:e5":{"s":2,"u":["Short direct (monoxenous) cycle.","Short direct (monoxenous) cycle : ingested cyst excysts into a 4-nucleate amoeba giving 8 trophozoites; in amoebiasis-infestation minuta forms live in the lumen and encyst, cysts leave in stool; in amoebiasis-disease they become histolytica forms whose lytic enzymes cause ulcers."],"dp":[]},"parasito-amoebiasis:e6":{"s":3,"u":["Dysentery: mucus + blood without faeces, épreintes, tenesmus.","Acute intestinal amoebiasis (amoebic dysentery) : incubation 1-4 weeks, sudden onset, severe abdominal pain, sometimes fever and vomiting; dysenteric syndrome: 10-15 stools/day of mucus and blood without faeces ('rectal sputum') , épreintes (colicky pain) and tenesmus ."],"dp":[]},"parasito-amoebiasis:e7":{"s":3,"u":["Liver abscess within 5 months in 95%: Fontan triad, anchovy-sauce pus.","Hepatic amoebiasis : via the portal system, within 5 months of dysentery in 95% ; pre-suppurative diffuse hepatitis or amoebic liver abscess : Fontan's triad ( fever 39-40 °C, painful hepatomegaly, right upper quadrant pain ), deterioration; 'anchovy-sauce' pus ; a diagnostic and therapeutic emergency."],"dp":[]},"parasito-amoebiasis:e10":{"s":4,"u":["Aspirate or drain large abscesses.","Surgery or image-guided aspiration for large abscesses."],"dp":[]},"parasito-amoebiasis:e8":{"s":4,"u":["Intestinal: 3 stool exams; visceral: ELISA serology.","Intestinal → stool diagnosis : fresh stool, 3 exams a day apart ; fresh exam for haematophagous trophozoites, Lugol, concentration for cysts; coproantigen ELISA .","Visceral → serology : raised ESR and neutrophils, ELISA serology (diagnosis and follow-up; stays positive for months to years; ESR and neutrophils normalise in 4-6 weeks); imaging for abscess."],"dp":[{"h":"Why stool is often negative in a liver abscess","t":"By the time an abscess forms, the intestinal episode may be months old and amoebae may no longer be shed in stool. The parasite is now in the liver, beyond the reach of a stool exam. That is why visceral amoebiasis is diagnosed by serology and imaging, not coprology. Source: the lecture's biological diagnosis slide."}]},"parasito-amoebiasis:e9":{"s":4,"u":["Tissue amoebicide (metronidazole) then contact amoebicide (paromomycin).","Treatment : tissue amoebicides (nitroimidazoles) that diffuse into tissues: metronidazole , ornidazole (1.5 g/day adult or 20-30 mg/kg/day for 10 days), tinidazole, secnidazole (2 g single dose); then a contact (luminal) amoebicide , active on minuta forms and cysts in the lumen: paromomycin (1.5 g/day adult, 50 mg/kg/day child; alternative intestinal antiseptics)."],"dp":[{"h":"Why two different amoebicides are needed","t":"Metronidazole is absorbed and reaches high levels in the gut wall and liver, killing invasive trophozoites, but little remains in the colonic lumen where minuta forms and cysts persist. Without a luminal agent like paromomycin, the patient stays a cyst carrier and can relapse or infect others. Source: the lecture's treatment slides."}]}},"meta":{"69lt7":{"a":"recall","vg":"parasito-amoebiasis:e0/recall/1"},"18uoxao":{"a":"recall","vg":"parasito-amoebiasis:e1/recall/1"},"ya3bea":{"a":"recall","vg":"parasito-amoebiasis:e2/recall/1"},"9k1guk":{"a":"recall","vg":"parasito-amoebiasis:e3/recall/1"},"13ptuh8":{"a":"recall","vg":"parasito-amoebiasis:e3/recall/2"},"tl7lz":{"a":"recall","vg":"parasito-amoebiasis:e4/recall/1"},"oq8du8":{"a":"recall","vg":"parasito-amoebiasis:e5/recall/1"},"me5lwn":{"a":"recall","vg":"parasito-amoebiasis:e6/recall/1"},"d6bx8a":{"a":"recall","vg":"parasito-amoebiasis:e7/recall/1"},"csxcfp":{"a":"recall","vg":"parasito-amoebiasis:e7/recall/2"},"1mclq59":{"a":"recall","vg":"parasito-amoebiasis:e7/recall/3"},"1wjok4n":{"a":"recall","vg":"parasito-amoebiasis:e8/recall/1"},"odzhu5":{"a":"recall","vg":"parasito-amoebiasis:e9/recall/1"},"16qfuj9":{"a":"relationship","vg":"parasito-amoebiasis:e9/relationship/1"},"1vnpe5i":{"a":"recall","vg":"parasito-amoebiasis:e7/recall/4"}},"explRev":"563c5f1af752"};
